Provide only the compilable Rust code."""

def extract_code(response: str) -> str:
    patterns = [
        r"```rust\n(.*?)```",
        r"```\n(.*?)```",
        r"```(.*?)```",
    ]

    for pattern in patterns:
        if matches := re.findall(pattern, response, re.DOTALL):
            code = matches[0].strip()
            if "fn main()" in code:
                return code

    if "fn main()" in response:
        return response.strip()

    raise ValueError("No valid Rust code found")

def validate_code(code: str) -> bool:
    required = [
        "fn main()",
        "use std::io",
        "stdin()",
        "println!",
    ]
    return all(req in code for req in required)

@backoff.on_exception(
    backoff.expo,
    (openai.RateLimitError, openai.APIError),
    max_tries=5,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    system_msg = """You are an expert Rust programmer. Generate only working Rust code that:
1. Uses standard input/output
2. Handles all edge cases
3. Includes proper error handling
4. Follows exact output format
Provide only the code without explanations."""

    async with semaphore:
        completion = await client.chat.completions.create(
            model="gpt-3.5-turbo-0125",
            messages=[
                {"role": "system", "content": system_msg},
                {"role": "user", "content": get_prompt(problem)}
            ],
            temperature=0.2,
            max_tokens=1600,
        )

    code = extract_code(completion.choices[0].message.content)
    if not validate_code(code):
        raise ValueError("Generated code missing required elements")

    return code
