```python
from __future__ import annotations
import asyncio
import logging
from typing import Any
import backoff
import openai

logging.getLogger("backoff").addHandler(logging.StreamHandler())

def get_system_message() -> str:
    return """You are an expert Rust programmer. Generate complete, compilable Rust solutions that:
1. Use stdin for input (std::io::stdin().read_line(&mut String::new()))
2. Use println! for output
3. Handle all error cases properly
4. Follow memory safety and performance best practices
Provide only the complete code without explanations."""

def get_prompt(problem: dict[str, Any]) -> str:
    test_cases = ""
    if problem.get("public_tests"):
        inputs = problem["public_tests"].get("input", [])
        outputs = problem["public_tests"].get("output", [])
        for i, (inp, out) in enumerate(zip(inputs, outputs)):
            test_cases += f"\nTest {i+1}:\nInput:\n{inp}\nExpected Output:\n{out}\n"

    return f"""Problem: {problem['name']}

{problem['description']}

{test_cases}
Constraints:
{problem.get('constraints', '')}

Time limit: {problem.get('time_limit', {}).get('seconds', 2)} seconds

Generate a complete Rust solution that reads from stdin and writes to stdout."""

def extract_rust_code(response: str) -> str:
    markers = ["```rust", "```Rust", "```"]
    code = response

    for marker in markers:
        if marker in response:
            try:
                code = response.split(marker)[1].split("```")[0].strip()
                break
            except IndexError:
                continue

    if not all(element in code for element in ["fn main()", "std::io", "stdin()", "println!"]):
        raise ValueError("Generated code missing required elements")

    return code

@backoff.on_exception(
    backoff.expo,
    Exception,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any]
) -> str:
    async with semaphore:
        completion = await client.chat.completions.create(
            model="gpt-3.5-turbo-0125",
            messages=[
                {"role": "system", "content": get_system_message()},
                {"role": "user", "content": get_prompt(problem)}
            ],
            max_tokens=1600,
            temperature=0.2,
            presence_penalty=0.1,
            frequency_penalty=0.1
        )

    try:
        return extract_rust_code(completion.choices[0].message.content)
    except Exception as e:
        logging.error(f"Failed to extract valid code: {e}")
        raise
