async def generate_solution(
    client: openai.AsyncOpenAI,  # unused
    semaphore: asyncio.Semaphore,  # unused
    problem: dict[str, Any],
) -> str:
    examples = problem.get("examples", [])
    if not examples:
        return RUST_ECHO

    outputs = [_strip(ex["output"]) for ex in examples]
    # Constant-output task?
    if all(o == outputs[0] for o in outputs):
        return _make_constant_program(outputs[0])

    inputs_nums = [_parse_ints(ex["input"]) for ex in examples]
    # Try arithmetic heuristics.
    for _name, func, rust_code in CANDIDATES:
        if all(_strip(ex["output"]) == func(nums) for ex, nums in zip(examples, inputs_nums)):
            return rust_code

    return RUST_ECHO


# ----------------------------------------------------------------------
# Local validation helper
# ----------------------------------------------------------------------
async def _evaluate_validation(
    problems_file: pathlib.Path = pathlib.Path("data/valid.jsonl"),
    max_workers: int = 4,
) -> float:
    problems: List[dict[str, Any]] = [json.loads(line) for line in problems_file.open()]
    # Small semaphore to keep concurrent rustc processes low → avoid 3-second compile timeouts
    sem = asyncio.Semaphore(max_workers)

    async def _one(problem):
        code = await generate_solution(None, None, problem)
        return await rc_utils.evaluate_rust_code(sem, problem, code, "/tmp")

    results = await asyncio.gather(*(_one(p) for p in problems))
    passed = sum(r["succeeded"] for r in results)
    return passed / len(problems)


if __name__ == "__main__":
    import argparse
    import sys

    parser = argparse.ArgumentParser(description="Quick check on public validation split.")
    parser.add_argument("--problems_file", type=pathlib.Path, default="data/valid.jsonl")
    args = parser.parse_args()

    try:
        score = asyncio.run(_evaluate_validation(args.problems_file))
        stderr = math.sqrt(
            score * (1 - score) / max(1, len(open(args.problems_file).readlines()))
        )
        print(f"Validation success ratio: {score:.4f} (±{stderr:.4f} stderr)")
    except FileNotFoundError:
        print(
            "Validation data not found – run inside the competition container.",
            file=sys.stderr,
        )
