scratch = pathlib.Path("scratch")
if scratch.exists():
    shutil.rmtree(scratch)
scratch.mkdir()


async def _evaluate():
    sem = asyncio.Semaphore(4)

    async def _one(problem):
        code = await module.generate_solution(None, sem, problem)
        return await rust_codecontests_utils.evaluate_rust_code(
            sem, problem, code, scratch
        )

    results = await asyncio.gather(*(_one(p) for p in problems))
    solved = sum(r["succeeded"] for r in results)
    print(f"Validation accuracy: {solved}/{len(results)} = {solved/len(results):.4f}")


asyncio.run(_evaluate())
